import{_ as n,C as r,o as a,c as s,a2 as o,b as l,w as i,a as d,E as c,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const b=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-X/Lectura_Catedra_Evaluacion_3.md"};function p(f,e,g,E,C,A){const t=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" tabindex="-1">Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-x" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre X)&quot;">​</a></h2><h3 id="eje-tematico-modelos-de-estimacion-cientifica-de-software-y-estudio-de-factibilidad" tabindex="-1">Eje Temático: Modelos de Estimación Científica de Software y Estudio de Factibilidad <a class="header-anchor" href="#eje-tematico-modelos-de-estimacion-cientifica-de-software-y-estudio-de-factibilidad" aria-label="Permalink to &quot;Eje Temático: Modelos de Estimación Científica de Software y Estudio de Factibilidad&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-estimacion-rigurosa-en-la-ingenieria" tabindex="-1">🧭 Introducción: La Estimación Rigurosa en la Ingeniería <a class="header-anchor" href="#🧭-introduccion-la-estimacion-rigurosa-en-la-ingenieria" aria-label="Permalink to &quot;🧭 Introducción: La Estimación Rigurosa en la Ingeniería&quot;">​</a></h2><p>Uno de los principales motivos por los cuales los proyectos de software exceden sus plazos y presupuestos es la incapacidad de estimar con rigor científico el <strong>tamaño, esfuerzo y tiempo de desarrollo</strong>. En el ejercicio profesional de la ingeniería, calcular el esfuerzo mediante métodos empíricos o intuitivos es inadmisible.</p><p>En el <strong>PST IV</strong>, los estudiantes aplican modelos paramétricos formales — <strong>Puntos de Función (IFPUG)</strong>, <strong>Puntos de Casos de Uso (UCP)</strong> y el modelo <strong>COCOMO II</strong> — para fundamentar técnicamente la propuesta de su Trabajo Especial de Grado.</p><hr><h2 id="📐-capitulo-i-el-metodo-de-puntos-de-funcion-ajustados-afp" tabindex="-1">📐 CAPÍTULO I: El Método de Puntos de Función Ajustados (AFP) <a class="header-anchor" href="#📐-capitulo-i-el-metodo-de-puntos-de-funcion-ajustados-afp" aria-label="Permalink to &quot;📐 CAPÍTULO I: El Método de Puntos de Función Ajustados (AFP)&quot;">​</a></h2><p>El estándar IFPUG permite calcular el tamaño funcional del software a través de dos componentes:</p>',10)),(a(),l(u,null,{default:i(()=>[c(t,{id:"mermaid-26",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20UFP%5B%22%F0%9F%93%A6%20Puntos%20de%20Funci%C3%B3n%20No%20Ajustados%20(UFP)%3Cbr%3E(EI%20%2B%20EO%20%2B%20EQ%20%2B%20ILF%20%2B%20EIF)%22%5D%20--%3E%20MULT%5B%22%E2%9C%96%EF%B8%8F%22%5D%0A%20%20%20%20VAF%5B%22%E2%9A%99%EF%B8%8F%20Factor%20de%20Ajuste%20de%20Valor%20(VAF)%3Cbr%3E14%20Caracter%C3%ADsticas%20Generales%20del%20Sistema%22%5D%20--%3E%20MULT%0A%20%20%20%20MULT%20--%3E%20AFP%5B%22%F0%9F%8E%AF%20PUNTOS%20DE%20FUNCI%C3%93N%20AJUSTADOS%20(AFP)%22%5D%0A%0A%20%20%20%20style%20UFP%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20VAF%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20MULT%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20AFP%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-formula-matematica-de-puntos-de-funcion-ajustados" tabindex="-1">1.1 Fórmula Matemática de Puntos de Función Ajustados: <a class="header-anchor" href="#_1-1-formula-matematica-de-puntos-de-funcion-ajustados" aria-label="Permalink to &quot;1.1 Fórmula Matemática de Puntos de Función Ajustados:&quot;">​</a></h3><p>$$\\text{AFP} = \\text{UFP} \\times (0.65 + 0.01 \\times \\sum_{i=1}^{14} C_i)$$ Donde $C_i$ son los 14 grados de influencia (comunicación de datos, procesamiento distribuido, rendimiento, facilidad operativa, reusabilidad, etc.) calificados de 0 a 5.</p><hr><h2 id="💻-capitulo-ii-el-modelo-cocomo-ii-constructive-cost-model" tabindex="-1">💻 CAPÍTULO II: El Modelo COCOMO II (Constructive Cost Model) <a class="header-anchor" href="#💻-capitulo-ii-el-modelo-cocomo-ii-constructive-cost-model" aria-label="Permalink to &quot;💻 CAPÍTULO II: El Modelo COCOMO II (Constructive Cost Model)&quot;">​</a></h2><p><strong>COCOMO II</strong> (desarrollado por la Universidad del Sur de California) es el estándar por excelencia para estimar el esfuerzo humano en personas-mes:</p><p>$$\\text{Esfuerzo (PM)} = A \\times (\\text{Size})^E \\times \\prod_{i=1}^{17} \\text{EM}_i$$</p><ul><li><strong>$A$ (Multiplicador Base):</strong> Típicamente $2.94$.</li><li><strong>$\\text{Size}$:</strong> Tamaño en KSLOC (miles de líneas de código fuente equivalentes) derivado de los Puntos de Función.</li><li><strong>$E$ (Factor de Escala):</strong> Determinado por 5 factores: precedencia del proyecto, flexibilidad de desarrollo, madurez del equipo, resolución de riesgos y cohesión.</li><li><strong>$\\text{EM}_i$ (Multiplicadores de Esfuerzo):</strong> 17 atributos del producto, plataforma, personal y proyecto (ej: capacidad de los analistas, restricciones de tiempo de ejecución, complejidad de la base de datos).</li></ul><hr><h2 id="⚖️-capitulo-iii-estudio-de-factibilidad-multidimensional-y-retorno-social-sroi" tabindex="-1">⚖️ CAPÍTULO III: Estudio de Factibilidad Multidimensional y Retorno Social (SROI) <a class="header-anchor" href="#⚖️-capitulo-iii-estudio-de-factibilidad-multidimensional-y-retorno-social-sroi" aria-label="Permalink to &quot;⚖️ CAPÍTULO III: Estudio de Factibilidad Multidimensional y Retorno Social (SROI)&quot;">​</a></h2><p>Además de la factibilidad técnica y legal (Ley de Infogobierno), en el Trabajo Especial de Grado se introduce el concepto de <strong>Retorno Social de la Inversión (SROI - Social Return on Investment)</strong>:</p><ul><li><strong>Ahorro Directo de Recursos Públicos:</strong> Cuantificación del costo evitado en licencias comerciales privativas (bases de datos Oracle/SQL Server, sistemas operativos Windows Server y licencias por usuario).</li><li><strong>Eficiencia en la Atención Ciudadana:</strong> Reducción del tiempo de respuesta en trámites de salud, educación o alimentación.</li><li><strong>Soberanía y Seguridad Nacional:</strong> Control total sobre el código fuente y los datos, eliminando puertas traseras (<em>backdoors</em>) y garantizando la autonomía tecnológica del país.</li></ul><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre X:</p><ol><li><strong>Memoria de Cálculo de Estimación de Esfuerzo:</strong> Aplicación formal de Puntos de Función o COCOMO II con tablas justificativas.</li><li><strong>Estudio de Factibilidad Integral:</strong> Con inventario de hardware de servidores, topología de red y marco normativo libre.</li><li><strong>Análisis de Impacto y Retorno Social (SROI):</strong> Demostración del beneficio tangible para la institución u organización.</li></ol>',15))])}const I=n(m,[["render",p]]);export{b as __pageData,I as default};
